export type Fields = { name: string; email: string; message: string };
export type Errors = Partial<Record<keyof Fields, string>>;

export function validate(v: Fields): Errors {
  const e: Errors = {};
  if (!v.name) e.name = "Name is required.";
  if (!v.email) e.email = "Email is required.";
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email)) e.email = "Enter a valid email address.";
  if (v.message.length < 20) e.message = "Message must be at least 20 characters.";
  return e;
}

export function readFields(f: FormData): Fields {
  const g = (k: string) => (f.get(k)?.toString() ?? "").trim();
  return { name: g("name"), email: g("email"), message: g("message") };
}
