import { Title } from "@solidjs/meta";
import { action, useSubmission } from "@solidjs/router";
import { Show, createSignal } from "solid-js";
import { readFields, validate, type Errors, type Fields } from "~/lib/contact";

type Result = { errors: Errors; values: Fields; success?: string };

const send = action(async (formData: FormData): Promise<Result> => {
  "use server";
  const { readFields, validate } = await import("~/lib/contact");
  const values = readFields(formData);
  const errors = validate(values);
  if (Object.keys(errors).length) return { errors, values };
  return { errors: {}, values, success: `Thanks, ${values.name}! Your message has been sent.` };
}, "contact-send");

export default function Contact() {
  const submission = useSubmission(send);
  const [clientErrors, setClientErrors] = createSignal<Errors | null>(null);
  const result = () => submission.result;
  const errors = () => clientErrors() ?? result()?.errors ?? {};
  const values = () => result()?.values;
  const success = () => (clientErrors() ? undefined : result()?.success);

  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={success()}>
        <p role="status">{success()}</p>
      </Show>
      <form
        action={send}
        method="post"
        novalidate
        onSubmit={e => {
          const errs = validate(readFields(new FormData(e.currentTarget)));
          if (Object.keys(errs).length) {
            e.preventDefault();
            e.stopImmediatePropagation();
            setClientErrors(errs);
          } else setClientErrors(null);
        }}
      >
        <div>
          <label for="name">Name</label>
          <input id="name" name="name" type="text" value={values()?.name ?? ""} />
          <Show when={errors().name}><span class="error">{errors().name}</span></Show>
        </div>
        <div>
          <label for="email">Email</label>
          <input id="email" name="email" type="email" value={values()?.email ?? ""} />
          <Show when={errors().email}><span class="error">{errors().email}</span></Show>
        </div>
        <div>
          <label for="message">Message</label>
          <textarea id="message" name="message" value={values()?.message ?? ""} />
          <Show when={errors().message}><span class="error">{errors().message}</span></Show>
        </div>
        <button type="submit">Send</button>
      </form>
    </>
  );
}
