import { createMiddleware } from "@solidjs/start/middleware";
import { getRequestEvent } from "solid-js/web";
import { readFields, validate } from "../lib/contact";

export default createMiddleware([
  async (event, next) => {
    if (event.req.method === "POST" && new URL(event.req.url).pathname === "/contact") {
      const form = await event.req.formData();
      const values = readFields(form);
      const errors = validate(values);
      const rev = getRequestEvent();
      if (rev) {
        rev.locals.contact = {
          errors,
          values,
          success: Object.keys(errors).length
            ? undefined
            : `Thanks, ${values.name}! Your message has been sent.`
        };
      }
      if (event.req.headers.get("x-enhanced")) return new Response(null, { status: 204 });
    }
    return next();
  }
]);
