import { Title } from "@solidjs/meta";
import { createAsync, query } from "@solidjs/router";
import { Show, createSignal } from "solid-js";
import { getRequestEvent } from "solid-js/web";
import { readFields, validate, type Errors } from "~/lib/contact";

const initial = query(async () => {
  "use server";
  return getRequestEvent()?.locals.contact ?? null;
}, "contact-initial");

export default function Contact() {
  const init = createAsync(() => initial(), { deferStream: true });
  const [errs, setErrs] = createSignal<Errors | null>(null);
  const [done, setDone] = createSignal<string | null>(null);
  const errors = () => errs() ?? init()?.errors ?? {};
  const success = () => (errs() ? null : (done() ?? init()?.success));
  const values = () => init()?.values;

  const onSubmit = async (e: SubmitEvent & { currentTarget: HTMLFormElement }) => {
    e.preventDefault();
    const form = e.currentTarget;
    const data = new FormData(form);
    const v = readFields(data);
    const found = validate(v);
    setErrs(Object.keys(found).length ? found : null);
    if (Object.keys(found).length) return;
    setDone(null);
    try {
      await fetch("/contact", {
        method: "POST",
        body: new URLSearchParams(data as any),
        headers: { "x-enhanced": "1" }
      });
    } catch {}
    setDone(`Thanks, ${v.name}! Your message has been sent.`);
  };

  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={success()}>
        <p role="status">{success()}</p>
      </Show>
      <form action="/contact" method="post" novalidate onSubmit={onSubmit}>
        <div>
          <label for="name">Name</label>
          <input id="name" name="name" type="text" value={values()?.name ?? ""} />
          <Show when={errors().name}><span class="error">{errors().name}</span></Show>
        </div>
        <div>
          <label for="email">Email</label>
          <input id="email" name="email" type="email" value={values()?.email ?? ""} />
          <Show when={errors().email}><span class="error">{errors().email}</span></Show>
        </div>
        <div>
          <label for="message">Message</label>
          <textarea id="message" name="message">{values()?.message ?? ""}</textarea>
          <Show when={errors().message}><span class="error">{errors().message}</span></Show>
        </div>
        <button type="submit">Send</button>
      </form>
    </>
  );
}
EOF
